edit = {json.loads(l)['qid']: json.loads(l) for l in open('/work/gen_2_edited.jsonl')}
for q in orig:
    o, e = orig[q], edit[q]
    if o['correct'] != e['correct']:
        tag = 'WRONG->RIGHT' if e['correct'] else 'RIGHT->WRONG'
        print(tag, q, 'finish o/e:', o['finish'], '/', e['finish'], 'closes o/e:', o['text'].count('</think>'), '/', e['text'].count('</think>'))

